import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec4, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const GroupCtor = THREE?.Group ?? Group;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  const root = new GroupCtor();
  root.name = 'hero-subhead';

  // ---- Backdrop / image plane (aspect matches atlas rect 512x320 = 1.6) ----
  const planeWidth = 3.2;
  const planeHeight = planeWidth / (512 / 320);
  const planeGeo = new PlaneGeometry(planeWidth, planeHeight, 1, 1);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
  });

  // Engineered gradient (vertical, subtle) as a placeholder + tint applied to the loaded texture.
  const gradientTint = mix(
    vec3(inkColor.r, inkColor.g, inkColor.b),
    vec3(inkColor.r * 1.35, inkColor.g * 1.35, inkColor.b * 1.35),
    uv().y
  );

  // Placeholder color before texture resolves.
  planeMat.colorNode = vec4(gradientTint, 1.0);
  planeMat.opacity = 0;

  const planeMesh = new Mesh(planeGeo, planeMat);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  let loadedTexture = null;
  const imageUrl = config?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      const texNode = texture(tex, uv());
      planeMat.colorNode = vec4(texNode.rgb.mul(gradientTint.mul(1.05).add(0.02)), texNode.a);
      planeMat.needsUpdate = true;
    }).catch(() => {
      // keep gradient placeholder on failure
    });
  }

  // ---- Text content (headline role subhead copy) ----
  const items =
    config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];

  const textGroup = new GroupCtor();
  textGroup.position.set(0, 0, 0.02);
  root.add(textGroup);

  const textMeshes = [];
  for (const item of items) {
    const rawText = String(item.text ?? '');
    // ASCII-safe sanitize: em-dash / middot / smart punctuation -> plain ASCII.
    const safeText = rawText
      .replace(/[\u2014\u2013]/g, '-')
      .replace(/[\u00b7\u2022]/g, '-')
      .replace(/[\u2018\u2019]/g, "'")
      .replace(/[\u201c\u201d]/g, '"')
      .replace(/[^\x00-\x7F]/g, '-');

    const fontSize = item?.typography?.fontSize ?? 42;

    const textObj = ctx.fontAtlas.createText(safeText, {
      fontSize,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 900,
    });
    textObj.position.set(0, 0, 0);
    textObj.userData._isSubheadText = true;
    // fade support: attempt to set opacity if material exists
    textGroup.add(textObj);
    textMeshes.push(textObj);
  }

  // ---- Accent underline (thin, <=10% of frame) ----
  const accentGeo = new BoxGeometry(0.9, 0.03, 0.02);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = vec4(vec3(accentColor.r, accentColor.g, accentColor.b), 1.0);
  accentMat.opacity = 0;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -planeHeight * 0.32, 0.03);
  root.add(accentMesh);

  // ---- Motion: weighted entrance + subtle idle breathing (no linear easing) ----
  root.position.y += 0.18;
  root.scale.setScalar(0.98);

  const tl = gsap.timeline({
    defaults: { ease: 'power3.out' },
  });

  tl.to(root.position, { y: root.position.y - 0.18, duration: 0.7 }, 0);
  tl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(planeMat, { opacity: 1, duration: 0.6 }, 0.05);
  tl.to(accentMat, { opacity: 0.9, duration: 0.5 }, 0.25);

  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.9 });
  idleTl.to(root.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();

    for (const t of textMeshes) {
      t.traverse?.((n) => {
        n.geometry?.dispose?.();
        if (n.material) {
          const mats = Array.isArray(n.material) ? n.material : [n.material];
          for (const m of mats) {
            m.map?.dispose?.();
            m.dispose?.();
          }
        }
      });
    }

    planeGeo.dispose();
    planeMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    loadedTexture?.dispose?.();
  };

  return root;
}
